fn ease(p: i32) -> i32 {
    (3 * p * p - p * p * p / 128) / 256
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let top: i32 = 30;
    let bot: i32 = h - 70;
    let ph: i32 = t % 180;
    let mut y: i32 = bot;
    host::display::clear(0x000000);
    if ph < 60 {
        y = bot - (bot - top) * ease(ph * 256 / 60) / 256;
        host::display::draw_string(8, 8, "UP", 0xffffff, 2);
    } else if ph < 90 {
        y = top;
        host::display::draw_string(8, 8, "TOP", 0x80ff80, 2);
    } else if ph < 150 {
        y = top + (bot - top) * ease((ph - 90) * 256 / 60) / 256;
        host::display::draw_string(8, 8, "DOWN", 0xffffff, 2);
    } else {
        host::display::draw_string(8, 8, "BOTTOM", 0x80ff80, 2);
    }
    let cx: i32 = w / 2;
    host::display::fill_rect(cx - 26, 0, 2, h, 0x303030);
    host::display::fill_rect(cx + 24, 0, 2, h, 0x303030);
    host::display::fill_rect(cx - 40, top + 40, 80, 2, 0x505050);
    host::display::fill_rect(cx - 40, bot + 40, 80, 2, 0x505050);
    host::display::fill_rect(cx - 20, y, 40, 40, 0xc0a020);
    host::display::present();
}
